head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > M > setMaxLength]<br/>컴포넌트의 maxlength 속성을 설정합니다.",
    "validation" : [
        "maxlength(필수) 파라미터로 컴포넌트에 입력 가능한 최대 길이를 숫자로 설정합니다.",
        "'' 설정 시 속성을 설정하지 않은 상태로 초기화합니다.",
        "-1 설정 시 속성을 설정하지 않은 상태로 초기화합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setMaxLength(5);
    target1.setValue("가나다라마바사");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}

// target2
scwin.btn_setValue2_onclick = function (e) {    
    target2.setMaxLength("");    
    target2.setValue("가나다라마바사");
    target2.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
}

// target3
scwin.btn_setValue3_onclick = function (e) {       
    target3.setMaxLength(-1);
    target3.setValue("가나다라마바사");
    target3.focus();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text(target3);
}


scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i < 4; i ++)
        eval("scwin.btn_setValue"+i+"_onclick()");
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i < 4; i ++)
        eval("scwin.btn_getText"+i+"_onclick()");
};
